#!/bin/sh
# Validates the first line of a commit message against Conventional Commits.
# Used by the lefthook commit-msg hook: check-commit-msg.sh <commit-msg-file>
set -eu

msg_file=${1:?usage: check-commit-msg.sh <commit-msg-file>}
subject=$(head -n 1 "$msg_file")

# Messages generated by git itself are always accepted.
case "$subject" in
  "Merge "* | "Revert "* | "fixup! "* | "squash! "* | "amend! "*) exit 0 ;;
esac

types='feat|fix|docs|style|refactor|perf|test|build|ci|chore|revert'
max_length=100
pattern="^($types)(\([a-z0-9._/-]+\))?!?: [^ ]"

if printf '%s\n' "$subject" | grep -Eq "$pattern" && [ "${#subject}" -le "$max_length" ]; then
  exit 0
fi

cat >&2 <<EOF
✗ Commit message does not follow Conventional Commits:
    $subject

  Expected: <type>(<scope>)!: <subject>   (max. $max_length characters)
  Types:    $(echo "$types" | tr '|' ' ')
  Example:  feat(agent): add memory collector
EOF
exit 1
